DROP TABLE IF EXISTS "product_groups";
DROP TABLE IF EXISTS "product_options";

CREATE TABLE "product_options" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" uuid NOT NULL,
  "group_no" integer NOT NULL,
  "group_name" varchar(50) NOT NULL,
  "option_name" varchar(120) NOT NULL,
  "image_url" text,
  "sort" integer NOT NULL DEFAULT 0,
  CONSTRAINT "UQ_product_option_name" UNIQUE ("product_id", "group_no", "option_name"),
  CONSTRAINT "CHK_product_option_group_no" CHECK ("group_no" > 0)
);

CREATE INDEX "IDX_product_options_product_order"
  ON "product_options" ("product_id", "group_no", "sort", "id");
